    "Rack A1": {"fr": "Baie A1", "de": "Rack A1", "zh": "机柜 A1", "hi": "रैक A1", "es": "Rack A1", "ar": "الحامل A1"},
    "Customer-facing web 99.9%": {"fr": "Web côté clients 99,9 %", "de": "Kundenseitiges Web 99,9 %", "zh": "面向客户的 Web 99.9%", "hi": "ग्राहक-सामने वेब 99.9%", "es": "Web de cara al cliente 99,9 %", "ar": "الويب الموجّه للعملاء 99.9%"},
    "0 3 * * 0 (every Sunday 03:00)": {"fr": "0 3 * * 0 (chaque dimanche à 03:00)", "de": "0 3 * * 0 (jeden Sonntag um 03:00)", "zh": "0 3 * * 0（每周日 03:00）", "hi": "0 3 * * 0 (हर रविवार 03:00)", "es": "0 3 * * 0 (cada domingo a las 03:00)", "ar": "0 3 * * 0 (كل يوم أحد الساعة 03:00)"},
    "/mnt/offsite/remotepower (leave blank for local-host only)": {"fr": "/mnt/offsite/remotepower (laisser vide pour l'hôte local uniquement)", "de": "/mnt/offsite/remotepower (leer lassen für nur den lokalen Host)", "zh": "/mnt/offsite/remotepower（留空则仅限本机）", "hi": "/mnt/offsite/remotepower (केवल स्थानीय होस्ट के लिए खाली छोड़ें)", "es": "/mnt/offsite/remotepower (déjelo en blanco para solo el host local)", "ar": "/mnt/offsite/remotepower (اتركه فارغًا للمضيف المحلي فقط)"},
    "/var/log/remotepower-audit.jsonl (blank = off)": {"fr": "/var/log/remotepower-audit.jsonl (vide = désactivé)", "de": "/var/log/remotepower-audit.jsonl (leer = aus)", "zh": "/var/log/remotepower-audit.jsonl（留空 = 关闭）", "hi": "/var/log/remotepower-audit.jsonl (खाली = बंद)", "es": "/var/log/remotepower-audit.jsonl (vacío = desactivado)", "ar": "/var/log/remotepower-audit.jsonl (فارغ = إيقاف)"},
