    "e.g. before_upgrade": {"fr": "p. ex. before_upgrade", "de": "z. B. before_upgrade", "zh": "例如 before_upgrade", "hi": "उदा. before_upgrade", "es": "p. ej. before_upgrade", "ar": "مثال: before_upgrade"},
