    "SMB credentials file": { "fr": "Fichier d'identifiants SMB", "de": "SMB-Anmeldedatendatei", "zh": "SMB 凭据文件", "hi": "SMB क्रेडेंशियल फ़ाइल", "es": "Archivo de credenciales SMB", "ar": "ملف بيانات اعتماد SMB" },
    "SNMP poll failing": { "fr": "Échec de l'interrogation SNMP", "de": "SNMP-Abfrage schlägt fehl", "zh": "SNMP 轮询失败", "hi": "SNMP पोलिंग विफल हो रही है", "es": "El sondeo SNMP está fallando", "ar": "فشل استقصاء SNMP" },
    "SNMP polling failed for 6+ hours": { "fr": "Interrogation SNMP en échec depuis plus de 6 heures", "de": "SNMP-Abfrage seit über 6 Stunden fehlgeschlagen", "zh": "SNMP 轮询已失败 6 小时以上", "hi": "SNMP पोलिंग 6+ घंटों से विफल है", "es": "El sondeo SNMP lleva fallando más de 6 horas", "ar": "فشل استقصاء SNMP منذ أكثر من 6 ساعات" },
