    "No hosts.": { "fr": "Aucun hôte.", "de": "Keine Hosts.", "zh": "没有主机。", "hi": "कोई होस्ट नहीं।", "es": "No hay hosts.", "ar": "لا يوجد مضيفون." },
    "No offline hosts.": { "fr": "Aucun hôte hors ligne.", "de": "Keine Offline-Hosts.", "zh": "没有离线主机。", "hi": "कोई ऑफ़लाइन होस्ट नहीं।", "es": "No hay hosts sin conexión.", "ar": "لا يوجد مضيفون غير متصلين." },
    "No online devices.": { "fr": "Aucun appareil en ligne.", "de": "Keine Geräte online.", "zh": "没有在线设备。", "hi": "कोई ऑनलाइन डिवाइस नहीं।", "es": "No hay dispositivos en línea.", "ar": "لا توجد أجهزة متصلة." },
    "No devices in scope.": { "fr": "Aucun appareil dans la portée.", "de": "Keine Geräte im Geltungsbereich.", "zh": "范围内没有设备。", "hi": "स्कोप में कोई डिवाइस नहीं।", "es": "No hay dispositivos en el alcance.", "ar": "لا توجد أجهزة ضمن النطاق." },
    "No devices to link.": { "fr": "Aucun appareil à lier.", "de": "Keine Geräte zum Verknüpfen.", "zh": "没有可关联的设备。", "hi": "लिंक करने के लिए कोई डिवाइस नहीं।", "es": "No hay dispositivos que vincular.", "ar": "لا توجد أجهزة للربط." },
    "No checks yet.": { "fr": "Aucun contrôle pour l'instant.", "de": "Noch keine Prüfungen.", "zh": "暂无检查。", "hi": "अभी कोई जाँच नहीं।", "es": "Aún no hay comprobaciones.", "ar": "لا توجد فحوصات بعد." },
    "No matching checks.": { "fr": "Aucun contrôle correspondant.", "de": "Keine passenden Prüfungen.", "zh": "没有匹配的检查。", "hi": "कोई मेल खाती जाँच नहीं।", "es": "No hay comprobaciones coincidentes.", "ar": "لا توجد فحوصات مطابقة." },
    "No matching monitors.": { "fr": "Aucun moniteur correspondant.", "de": "Keine passenden Monitore.", "zh": "没有匹配的监控。", "hi": "कोई मेल खाता मॉनिटर नहीं।", "es": "No hay monitores coincidentes.", "ar": "لا توجد مراقبات مطابقة." },
    "No matching rows.": { "fr": "Aucune ligne correspondante.", "de": "Keine passenden Zeilen.", "zh": "没有匹配的行。", "hi": "कोई मेल खाती पंक्ति नहीं।", "es": "No hay filas coincidentes.", "ar": "لا توجد صفوف مطابقة." },
    "No matching assets.": { "fr": "Aucun actif correspondant.", "de": "Keine passenden Assets.", "zh": "没有匹配的资产。", "hi": "कोई मेल खाती संपत्ति नहीं।", "es": "No hay activos coincidentes.", "ar": "لا توجد أصول مطابقة." },
    "No findings.": { "fr": "Aucune constatation.", "de": "Keine Funde.", "zh": "没有发现项。", "hi": "कोई निष्कर्ष नहीं।", "es": "Sin hallazgos.", "ar": "لا توجد نتائج." },
    "No content.": { "fr": "Aucun contenu.", "de": "Kein Inhalt.", "zh": "没有内容。", "hi": "कोई सामग्री नहीं।", "es": "Sin contenido.", "ar": "لا يوجد محتوى." },
    "No recent activity.": { "fr": "Aucune activité récente.", "de": "Keine aktuelle Aktivität.", "zh": "近期没有活动。", "hi": "कोई हालिया गतिविधि नहीं।", "es": "Sin actividad reciente.", "ar": "لا يوجد نشاط حديث." },
    "No open alerts — all clear.": { "fr": "Aucune alerte ouverte — tout va bien.", "de": "Keine offenen Alarme — alles in Ordnung.", "zh": "没有未处理的告警 — 一切正常。", "hi": "कोई खुला अलर्ट नहीं — सब ठीक है।", "es": "No hay alertas abiertas: todo correcto.", "ar": "لا توجد تنبيهات مفتوحة — كل شيء على ما يرام." },
    "No CVEs found.": { "fr": "Aucune CVE trouvée.", "de": "Keine CVEs gefunden.", "zh": "未发现 CVE。", "hi": "कोई CVE नहीं मिला।", "es": "No se encontraron CVE.", "ar": "لم يتم العثور على ثغرات CVE." },
