    "e.g. every weekday at 6am, or the 1st of each month at midnight": { fr: "p. ex. chaque jour de semaine à 6 h, ou le 1er de chaque mois à minuit",de: 'z. B. jeden Wochentag um 6 Uhr, oder am 1. jedes Monats um Mitternacht',  "zh": "如 每个工作日早上 6 点，或每月 1 日午夜", "hi": "जैसे हर कार्यदिवस 6 बजे, या हर माह की 1 तारीख आधी रात", "es": "p. ej. cada día laborable a las 6 h, o el día 1 de cada mes a medianoche", "ar": "مثل كل يوم عمل الساعة 6 صباحًا، أو أول كل شهر منتصف الليل" },
    "e.g. monitor, server, cloud": { fr: "p. ex. monitor, server, cloud",de: 'z. B. monitor, server, cloud',  "zh": "如 monitor、server、cloud", "hi": "जैसे monitor, server, cloud", "es": "p. ej. monitor, servidor, nube", "ar": "مثل monitor، server، cloud" },
    "e.g. nginx htop": { fr: "p. ex. nginx htop",de: 'z. B. nginx htop',  "zh": "如 nginx htop", "hi": "जैसे nginx htop", "es": "p. ej. nginx htop", "ar": "مثل nginx htop" },
